insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('G8dXpNG', 'Remada curvada com barra EZ e pegada inversa', array['Fique de pe com os pes na largura dos ombros e joelhos levemente flexionados', 'Segure a barra EZ com as palmas das maos voltadas para cima e maos na largura dos ombros', 'Posicione o tronco e permita que os bracos alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para tras e aproxime o puxador ou peso do seu tronco', 'Mantenha as palmas das maos na pegada escolhida sem dobrar os punhos para tras', 'Estenda os bracos para a frente novamente sem deixar o tronco balancar']),
  ('g9AsZ8P', 'Remada unilateral com kettlebell', array['Fique de pe com os pes na largura dos ombros, segurando um kettlebell em uma mao com a palma voltada para baixo', 'Flexione levemente os joelhos e incline o tronco para a frente a partir do quadril, com a coluna firme e o core ativado', 'Posicione o tronco e permita que os bracos alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para tras e aproxime o puxador ou peso do seu tronco', 'Mantenha ambos os ombros nivelados e resista a inclinacao em direcao ao braco em movimento', 'Estenda os bracos para a frente novamente sem deixar o tronco balancar; alterne os lados quando o exercicio exigir']),
  ('GaSzzuh', 'Back lever', array['Comece pendurado em uma barra fixa com as palmas das maos voltadas para baixo, maos logo alem da largura dos ombros', 'Contraia o tronco e puxe as omoplatas para baixo e para tras', 'Contraia o abdomen e encontre uma posicao que voce consiga manter sem prender a respiracao', 'Contraia a regiao central do corpo e mantenha a posicao enquanto respira normalmente', 'Continue respirando de forma constante enquanto mantem a mesma linha corporal', 'Mantenha a forma pelo tempo planejado e entao saia da posicao com controle']),
  ('gAwDzB3', 'Triceps na polia com barra V', array['Conecte um acessorio em barra V na maquina de cabo na regulagem mais alta', 'Fique de frente para a maquina de cabo em uma postura estável com os pes na largura dos ombros', 'Fique a uma distancia suficiente da pilha de pesos para que o cabo permaneca esticado', 'Mantenha os cotovelos proximos as costelas e estenda os bracos contra o cabo', 'Mantenha os cotovelos proximos ao corpo em vez de deixar os ombros balancarem', 'Retorne pelo mesmo caminho em um ritmo controlado']),
  ('Gchi5Tr', 'Tríceps alternado no cabo', array['Fique de frente para a polia com uma base estável e os pés na largura dos ombros', 'Segure o puxador com a mão direita e eleve o braço para que ele fique paralelo ao chão e o cotovelo flexionado a 90 graus', 'Posicione os braços firmemente antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover a carga', 'Conclua o movimento de um lado antes de iniciar o outro', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição e alterne os lados quando necessário']),
  ('GdMa1ET', 'Flexão de ombros inclinada', array['Ajuste o banco a aproximadamente 45 graus', 'Apoie as mãos no banco logo acima da largura dos ombros', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para esticar os braços, mantendo a linha do corpo intacta']),
  ('gdPIyyO', 'Elevação de pernas suspensa em L', array['Fique suspenso em uma barra fixa com os braços estendidos e as palmas das mãos viradas para frente', 'Contraia o tronco e eleve as pernas em direção à barra, mantendo-as esticadas', 'Contraia o abdômen e mantenha os ombros firmes no suporte', 'Eleve as pernas contraindo o tronco e movendo os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a lombar da posição correta', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('gEyURal', 'Stiff unilateral com barra', array['Fique em pé com os pés na largura dos quadris, segurando uma barra à frente das coxas com as palmas para baixo', 'Transfira o peso para o pé esquerdo e tire o pé direito ligeiramente do chão', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre os quadris para frente para ficar em pé sem inclinar para trás no topo']),
  ('gf3ZjB9', 'Hack squat no trenó com pés juntos', array['Ajuste o aparelho com um peso confortável e posicione-se com as costas apoiadas no encosto', 'Coloque os pés na largura dos ombros na plataforma com os dedos ligeiramente voltados para fora', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos e evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a descida seguinte']),
  ('gfk9kD4', 'Agachamento livre com barra acima da cabeça', array['Fique em pé com os pés na largura dos ombros e os dedos ligeiramente voltados para fora', 'Segure a barra com uma pegada aberta, posicionando-a acima da cabeça com os braços esticados', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos e evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a descida seguinte']),
  ('gFyFj9z', 'Afundo com step e halteres', array['Posicione-se em frente a um step ou plataforma segurando um halter em cada mão com as palmas voltadas para as coxas', 'Coloque o pé direito no step garantindo que todo o pé esteja na superfície', 'Apoie totalmente o pé da frente na plataforma antes de transferir o peso para ele', 'Suba na plataforma empurrando pelo pé da frente para ficar erguido', 'Mantenha o pé da frente firme e evite que o joelho desabe para dentro', 'Empurre pelo pé da frente para retornar ao início e alterne as pernas conforme planejado']),
  ('gGNQmVt', 'Agachamento búlgaro com barra', array['Fique em pé com os pés na largura dos ombros, segurando uma barra na parte superior das costas', 'Dê um passo longo para frente com uma perna mantendo o tronco erguido', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos e evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a descida seguinte']),
  ('gH5fRsC', 'Elevação frontal alternada sentada com halteres', array['Sente-se em um banco com as costas retas e os pés apoiados', 'Segure um halter em cada mão com as palmas voltadas para o corpo e braços estendidos ao lado', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Levante os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco firme', 'Termine o movimento de um lado antes que o outro lado assuma o controle', 'Abaixe os braços lentamente para os lados sem balançar o peso; troque de lado quando a série exigir']),
  ('Gi2BXfK', 'Tríceps coice alternado em pé com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, com a coluna firme', 'Posicione os braços antes de estender os cotovelos', 'Mantenha o braço junto ao tronco e estique o cotovelo para trás', 'Termine o movimento de um lado antes que o outro lado assuma o controle', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; troque de lado quando a série exigir']),
  ('GibBPPg', 'Marcha na ponte glútea', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Contraia os glúteos e eleve o quadril do chão, formando uma linha reta dos joelhos aos ombros', 'Apoie os pés e impeça que as costelas se expandam enquanto o quadril se prepara para subir', 'Pressione com os pés e eleve o quadril até que o tronco e as coxas fiquem alinhados', 'Pare quando o quadril estiver alinhado com o tronco; não arqueie mais a região lombar', 'Abaixe o quadril de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('Gk1r408', 'Remada alta com pegada fechada com peso na barra fixa', array['Posicione-se em frente à estrutura de paralelas e segure as barras paralelas com as palmas voltadas para cima, mãos na largura dos ombros', 'Suspenda-se nas barras com os braços retos, pés fora do chão e corpo reto', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Abaixe até esticar os braços sem cair repentinamente do topo']),
  ('GKEH6jj', 'Supino inclinado unilateral com cabo', array['Ajuste a máquina de cabo na posição de polia baixa', 'Sente-se em um banco inclinado virado para longe da máquina de cabo', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; troque de lado quando a série exigir']),
  ('gKozT8X', 'Levantamento terra unilateral com halter', array['Fique em pé com os pés na largura dos quadris, segurando um halter na mão direita', 'Transfira o peso para a perna esquerda e tire o pé direito levemente do chão', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás', 'Empurre o quadril para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre o quadril para a frente para ficar totalmente em pé sem inclinar para trás no topo']),
  ('Gm2Uv1z', 'Extensão de tríceps deitada na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e os joelhos flexionados a 90 graus', 'Segure um halter com ambas as mãos e estenda os braços para cima em direção ao teto', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda através dos cotovelos para mover o peso', 'Mantenha a bola estável e use os pés para controlar o seu equilíbrio', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('gMyx3Qn', 'Flexão escapular', array['Comece em posição de prancha alta com as mãos diretamente abaixo dos ombros e o corpo em linha reta', 'Abaixe o peito em direção ao chão, mantendo os cotovelos próximos ao corpo', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em uma única linha', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para os braços estendidos, mantendo a linha do corpo intacta']),
  ('Gn5FwYT', 'Abdominal na bola suíça (amplitude total com as mãos atrás da cabeça)', array['Sente-se na bola suíça com os pés apoiados e os joelhos flexionados a noventa graus', 'Posicione as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('Gnfo4FM', 'Agachamento com barra alta', array['Fique de pé com os pés na largura dos ombros e os dedos levemente virados para fora', 'Posicione a barra na parte superior das costas, apoiando-a nos trapézios', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e então inicie a descida seguinte']),
  ('GNhAeJ0', 'Rosca martelo com halteres (com arm blaster)', array['Fique em pé com um halter em cada mão, com as palmas voltadas para o tronco', 'Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até que fiquem voltadas para a frente', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos às costelas; evite balançar o corpo', 'Mantenha as palmas voltadas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada']),
  ('goJ6ezq', 'Elevação lateral no cabo', array['Fique em pé com os pés na largura dos ombros e segure os puxadores do cabo com as palmas para baixo', 'Mantenha os braços retos e o core contraído', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros sem inclinar o tronco ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('GOJKFfO', 'Rosca isquiotibiais com chute diagonal unilateral na bola de exercício', array['Comece deitado de costas com as pernas estendidas e os calcanhares apoiados no topo da bola suíça', 'Posicione os braços ao lado do corpo para estabilidade', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o esforço', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada; alterne os lados quando necessário']),
  ('Gpn4ADc', 'Desenvolvimento por trás da nuca no Smith', array['Ajuste a altura do banco no aparelho Smith para que a barra fique na altura dos ombros', 'Fique de pé com os pés na largura dos ombros e os joelhos semiflexionados', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('GrO65fd', 'Supino declinado com barra', array['Prenda os pés em um banco declinado, mantendo a cabeça abaixo dos quadris', 'Segure a barra com as palmas voltadas para baixo logo acima da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('gscGLOU', 'Rosca de bíceps deitado de lado com o peso do corpo', array['Acomode-se de lado com as pernas estendidas e a cabeça apoiada pelo braço', 'Mantenha a parte superior do braço contra o corpo e flexione o cotovelo para trazer o antebraço em direção ao ombro', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e permita que a flexão do cotovelo levante o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('GSDioYu', 'Alongamento de parte superior das costas', array['Fique em pé com os pés na largura dos ombros.', 'Estenda os braços à sua frente, paralelos ao solo.', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Mantenha um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('gSO0KpB', 'Abdominal com braços no peito', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão.', 'Cruze os braços sobre o peito.', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir.', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição.']),
  ('gSw59a4', 'Elevação posterior de ombro unilateral deitada com halter', array['Posicione-se de bruços em um banco reto com um halter em uma mão, palma voltada para dentro.', 'Estenda o braço para baixo em direção ao chão, mantendo-o próximo ao corpo.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Eleve os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Mantenha ambos os ombros nivelados e evite girar o corpo em direção ao braço que está trabalhando.', 'Abaixe os braços lentamente para os lados sem balançar o peso; alterne os lados quando necessário.']),
  ('gTGciXz', 'Engatinhar em quatro apoios', array['Fique de quatro com as mãos diretamente sob os ombros e os joelhos diretamente sob os quadris.', 'Antes de se mover, tire os joelhos levemente do chão, mantendo as costas retas e o core contraído.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante.', 'Mantenha o padrão repetível à medida que a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('gtO1ErP', 'Mergulho em três bancos com peso', array['Sente-se na borda de um banco com as mãos segurando a borda, dedos apontados para a frente.', 'Avance os pés, deslizando o quadril para fora do banco e sustentando o peso com os braços.', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para abaixar entre os suportes; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis.', 'Pressione com as mãos para subir, depois ajuste os ombros antes de outra repetição.']),
  ('Gu2ENkm', 'Supino declinado invertido com pegada fechada no Smith', array['Ajuste a máquina Smith para a posição declinada.', 'Deite-se no banco com os pés presos sob os suportes.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as barras para longe, mantendo o tronco firme.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('Gu2rNJd', 'Agachamento no Smith com cadeira', array['Ajuste a altura da barra da máquina Smith para uma posição confortável.', 'Fique em pé e posicione os pés na largura dos ombros, com as pontas levemente viradas para fora.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('gUjqdei', 'Agachamento cruzado', array['Fique em pé e posicione os pés na largura dos ombros.', 'Dê um passo na diagonal para trás e cruzando o corpo com o pé direito, passando-o por trás da perna esquerda.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('GUT8I22', 'Levantamento terra na máquina', array['Ajuste a altura do assento e da plataforma para a posicão desejada', 'Sente-se na máquina com as costas apoiadas no encosto e os pés apoiados na plataforma', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Projete os quadris para frente para ficar em pé sem se inclinar para trás no topo']),
  ('guT8YnS', 'Barra fixa com pegada supinada', array['Suspenda-se em uma barra fixa com as palmas voltadas para você e as mãos na largura dos ombros', 'Contraia o tronco e puxe o corpo flexionando os cotovelos, levando o peito em direção à barra', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e leve a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça até esticar os braços sem despencar do topo']),
  ('gVlnLIJ', 'Rosca inversa unilateral no cabo', array['Fique de frente para a máquina de cabo em uma postura estável com os pés na largura dos ombros', 'Segure a alça do cabo com as palmas voltadas para baixo', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Enrole o peso com as palmas voltadas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que trabalha', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados; troque de lado quando o exercício exigir']),
  ('gvsWLQw', 'Rosca concentrada com halter', array['Sente-se em um banco com as pernas afastadas e um halter em uma mão, apoiando o cotovelo na parte interna da coxa', 'Estenda totalmente o braço e segure o halter com as palmas voltadas para cima', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo erguer o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('Gw2HFvW', 'Crucifixo inclinado unilateral com halter', array['Ajuste o banco inclinado para um ângulo de 30 a 45 graus', 'Sente-se no banco com um halter em uma mão, apoiando-o na coxa', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco largo', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que trabalha', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair; troque de lado quando o exercício exigir']),
