  ('hq2hyDH', 'Rosca scott com halteres em pe', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão com as palmas voltadas para frente', 'Apoie a parte de trás dos braços no banco scott ou em um banco inclinado, com os cotovelos relaxados', 'Posicione o braço em trabalho contra o apoio e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o apoio', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('hrrS0Ed', 'Elevacao lateral sentada com halteres', array['Apoie ambos os pés no chão sentado em um banco; um halter em cada mão, descansando nas coxas', 'Mantenha a coluna em uma posição neutra confortável e o core ativado', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar o corpo ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para os lados sem balançar o peso']),
  ('hrVQWvE', 'Stiff com barra', array['Fique em pé com os pés na largura dos ombros e os dedos apontados para frente', 'Segure a barra com as palmas voltadas para baixo, mãos logo abaixo da largura dos ombros', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Envie os quadris para trás com uma leve flexão dos joelhos, descendo a carga perto das pernas até sentir os posteriores de coxa alongarem', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre os quadris para frente para ficar erguido sem inclinar para trás no topo']),
  ('HsjbB1z', 'Afundo dinâmico no smith', array['Prepare a máquina smith com a barra na altura do quadril', 'Fique de costas para a máquina com uma base estável e pés na largura dos ombros', 'Posicione a base com largura suficiente para se equilibrar antes de flexionar os joelhos', 'Avance no movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite que o joelho caia para dentro', 'Empurre pelo pé da frente para retornar ao início e alterne as pernas conforme planejado']),
  ('HsvHqgf', 'Agachamento com halteres', array['Fique de pé com os pés na largura dos ombros, segurando um halter em cada mão ao lado do corpo', 'Com o peito estufado e o abdômen contraído, abaixe o corpo flexionando joelhos e quadris, como se fosse sentar em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e o quadril subindo juntos, evitando que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('ht8xDrP', 'Desenvolvimento militar por trás da cabeça no smith', array['Ajuste a altura do banco no smith para que a barra fique na altura dos ombros', 'Fique de pé com os pés na largura dos ombros e joelhos semi-flexionados', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('HtfCpfi', 'Polichinelo', array['Fique de pé com os pés na largura dos ombros e braços ao lado do corpo', 'Antes de se mover, flexione levemente os joelhos e salte de forma explosiva', 'Flexione levemente quadris e joelhos para preparar o salto', 'Carregue as pernas com uma pequena flexão, depois impulsione pelo chão e pouse suavemente', 'Aterrisse com quadris e joelhos flexionados e deixe os pés absorverem o impacto', 'Absorva a aterrissagem pelos quadris e joelhos antes de repetir']),
  ('hTLtkXL', 'Desenvolvimento sentado com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e pés apoiados', 'Segure o elástico de resistência com ambas as mãos, palmas viradas para a frente, e traga-o até a altura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para cima mantendo o tronco contraído', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('HUEqZ1y', 'Agachamento sumô com barra', array['Fique de pé com os pés mais afastados que a largura dos ombros e pontas dos pés voltadas ligeiramente para fora', 'Coloque uma barra na parte superior das costas, apoiando-a nos ombros', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e o quadril subindo juntos, evitando que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('hvHhCv8', 'Elevação frontal no cabo', array['Fique de pé com os pés na largura dos ombros e joelhos semi-flexionados', 'Segure a alça do cabo com as palmas para baixo e os braços estendidos à sua frente', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco imóvel', 'Pare próximo à altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('hvV79Si', 'Remada baixa no cabo', array['Sente-se na máquina com os pés apoiados nos suportes e joelhos semi-flexionados', 'Segure as alças com as palmas voltadas para baixo', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estenda os braços para a frente novamente sem deixar o tronco projetar-se bruscamente']),
  ('hVzPY5j', 'Corda naval', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados', 'Segure uma ponta da corda em cada mão com as palmas voltadas uma para a outra', 'Comece em um ritmo que permita que pés e braços se movam em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento fluido e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
  ('hwygydB', 'Rosca concentrada com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Segure um halter em uma mão com a palma voltada para cima, apoiando o cotovelo na bola suíça', 'Posicione o braço que está trabalhando contra o apoio, deixando o cotovelo livre para flexionar', 'Flexione o peso enquanto os braços permanecem em contato com o apoio', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('Hx1WC8I', 'Tríceps inclinado no cabo', array['Ajuste a polia do cabo na posição baixa', 'Conecte uma barra reta ao cabo', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda através dos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('hxyTtWj', 'Elevação lateral sentada com halteres', array['Apoie ambos os pés enquanto estiver sentado em um banco, com um halter em cada mão apoiado nas coxas', 'Mantenha a coluna em uma posição neutra e confortável com o core contraído', 'Comece com uma carga viável e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto', 'Abaixe os braços lentamente para os lados sem balançar o peso']),
  ('Hy9D21L', 'Flexão lateral a 45 graus', array['Fique em pé com os pés na largura dos ombros e os braços estendidos ao longo do corpo', 'Com as costas retas e o core contraído, incline o tronco para um lado com controle, abaixando a mão em direção ao joelho', 'Fique em pé ou sentado erguido com a pelve voltada para a frente', 'Incline-se lateralmente pela cintura sem torcer ou deixar os quadris se moverem', 'Deixe a lateral do tronco trabalhar, sem torcer ou mover os quadris', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('HYe1ZqR', 'Crucifixo inclinado com halteres na bola suíça', array['Ajuste o banco para aproximadamente 45 graus', 'Sente-se em uma bola suíça e role para a frente até que a parte superior das costas esteja apoiada no banco inclinado', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga']),
  ('HZgQPxh', 'Afastamento abdominal suspenso', array['Conecte um fita de suspensão a um ponto de ancoragem alto e ajuste as tiras na altura da cintura', 'Fique de costas para o ponto de ancoragem e segure as alças com os braços estendidos à sua frente', 'Contraia o abdômen e mantenha a pelve encaixada antes de afastar os braços', 'Afaste os braços mantendo as costelas e a pelve alinhadas, pare antes que a região lombar ceda', 'Pare de avançar quando a região lombar começar a ceder', 'Puxe de volta para o início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('i11JWU7', 'Tríceps unilateral na polia alta com pegada inversa', array['Fique de costas para a máquina de cabo com uma postura firme e pés na largura dos ombros', 'Segure a alça do cabo com as palmas voltadas para cima e estenda o braço acima da cabeça, mantendo o cotovelo próximo à cabeça', 'Posicione o braço antes de estender o cotovelo', 'Mantenha o braço apontado para cima e estenda o cotovelo sem abrir as costelas', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que está trabalhando', 'Flexione o cotovelo lentamente para retornar ao início da próxima repetição, alterne os lados quando necessário']),
  ('I1OBLnn', 'Supino Svend com peso', array['Fique em pé com os pés na largura dos ombros e segure uma anilha na altura do peito com as duas mãos', 'Mantenha os cotovelos levemente flexionados e as palmas das mãos voltadas uma para a outra', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para frente mantendo o tronco contraído', 'Mantenha os punhos alinhados e use um movimento de ombro que pareça natural', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('I3tsCnC', 'Elevação de pernas na barra fixa', array['Segure-se em uma barra fixa com os braços estendidos e as palmas das mãos voltadas para frente', 'Contraia o tronco e eleve as pernas à sua frente, mantendo-as estendidas', 'Contraia o abdômen e mantenha os ombros firmes no suporte', 'Eleve as pernas contraindo o tronco e movimentando os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Desça as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('I4hDWkc', 'Flexão', array['Comece em uma posição de prancha alta com as mãos logo abaixo dos ombros e os pés juntos', 'Contraia o tronco e abaixe o corpo em direção ao chão flexionando os cotovelos, mantendo o corpo em linha reta', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para a posição com os braços estendidos, mantendo a linha do corpo intacta']),
