  ('I4tibZG', 'Remada alta alternada com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em cada mão com as palmas voltadas para baixo', 'Flexione os joelhos levemente e incline o tronco à frente pelos quadris, com a coluna firme e o peito estufado', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Impulsione com as pernas e os quadris, depois guie o peso até a posição de recepção', 'Finalize o movimento de um lado antes que o outro lado comece', 'Fique em pé para finalizar, depois desça o peso de forma controlada antes da próxima repetição; alterne os lados quando necessário']),
  ('i5cEhka', 'Flexão inclinada', array['Posicione as mãos no chão logo abaixo dos ombros, com os pés elevados em uma superfície estável', 'Segure o corpo em linha reta da cabeça aos pés, ativando os músculos do core', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para a posição com os braços estendidos, mantendo a linha do corpo intacta']),
  ('I6Ca0a7', 'Tríceps testa com barra EZ', array['Deite-se em um banco com os pés apoiados e a cabeça na extremidade do banco', 'Segure a barra EZ com pegada fechada, palmas voltadas para cima, e estenda os braços para cima sobre o peito', 'Posicione os braços firmes antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('i6LWjok', 'Pullover com barra', array['Deite-se em um banco com a cabeça em uma extremidade e os pés no chão', 'Segure uma barra com uma pegada na largura dos ombros e estenda os braços direto acima do peito', 'Abaixe as costelas e mantenha uma leve flexão nos cotovelos antes de descer o peso', 'Desça o peso em arco atrás da cabeça até sentir um alongamento confortável nos ombros', 'Mantenha as costelas abaixadas enquanto os braços passam por cima da cabeça', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('i8BdLTK', 'Pullover com halter com braços retos', array['Deite-se em um banco com a cabeça em uma extremidade e os pés firmemente apoiados no chão', 'Segure um halter com ambas as mãos e estenda os braços direto acima do peito', 'Abaixe as costelas e mantenha uma leve flexão nos cotovelos antes de descer o peso', 'Desça o peso em arco atrás da cabeça até sentir um alongamento confortável nos ombros', 'Mantenha as costelas abaixadas enquanto os braços passam por cima da cabeça', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('ia6kIIl', 'Agachamento parcial', array['Fique em pé com os pés na largura dos ombros', 'Antes de se mover, flexione os joelhos e abaixe o corpo como se fosse sentar em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, então inicie a próxima descida']),
  ('Ia7tumC', 'Elevação de panturrilha sentada unilateral com halter', array['Sente-se em um banco ou cadeira com os pés apoiados e um halter apoiado na coxa direita', 'Estenda a perna esquerda para a frente, mantendo o pé flexionado', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece estável', 'Eleve-se sobre a ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente; alterne os lados quando necessário']),
  ('iaapw0g', 'Rosca francesa sentada com barra EZ', array['Sente-se em um banco com as costas retas e os pés apoiados', 'Segure a barra EZ com as palmas voltadas para baixo, mãos na largura dos ombros', 'Posicione os braços firmemente antes de estender os cotovelos', 'Mantenha a parte superior dos braços estável e estenda os cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('IaGQCrC', 'Flexão suspensa', array['Escolha um equipamento de suspensão e ajuste-o para uma altura adequada', 'Fique de costas para o ponto de ancoragem e segure as alças com as palmas voltadas para baixo', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta aos braços estendidos, mantendo a linha do corpo intacta']),
  ('IBj3nsn', 'Pés rápidos', array['Fique em pé com os pés na largura dos ombros e os braços ao lado do corpo', 'Comece a mover os pés rapidamente para cima e para baixo, como se estivesse correndo no lugar', 'Comece em um ritmo que permita aos pés e braços se moverem em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento fluido e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
  ('iCPqbki', 'Remada sentada na máquina com pegada neutra', array['Ajuste a altura do assento e os apoios para os pés para garantir a postura correta', 'Sente-se na máquina com os pés apoiados e os joelhos levemente flexionados', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('iDGtjyi', 'Alongamento de peito e parte frontal do ombro', array['Fique em pé e posicione os pés na largura dos ombros.', 'Estenda os braços diretamente à sua frente na altura dos ombros.', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do alongamento até sentir uma leve tensão; continue respirando e evite balançar.', 'Mantenha um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado se necessário.']),
  ('Ie9UGty', 'Panturrilha sentada na máquina', array['Ajuste o assento da máquina para que seus ombros fiquem alinhados com o apoio da alavanca.', 'Posicione a ponta dos pés na parte inferior da plataforma e os joelhos sob o apoio da alavanca.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Eleve-se na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente.']),
  ('IeDEXTe', 'Agachamento e panturrilha sentados na máquina leg press', array['Mova o assento do leg press até que os joelhos fiquem levemente flexionados no início.', 'Sente-se na máquina com as costas no encosto e os pés apoiados na plataforma, na largura dos ombros.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os pontas dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a descida seguinte.']),
  ('IENzBdA', 'Rosca dragão com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para cima.', 'Mantenha a barra pendurada com os braços estendidos à frente das coxas.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e permita que a flexão do cotovelo levante o peso.', 'Abaixe até que os cotovelos estejam quase estendidos, mantendo a parte superior dos braços imóvel.']),
  ('IeTIEqg', 'Agachamento frontal com barra', array['Comece em pé com os pés na largura dos ombros e os dedos levemente apontados para fora.', 'Segure a barra à frente do peito com as mãos na largura dos ombros e os cotovelos apontados para frente.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os pontas dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a descida seguinte.']),
  ('iFsqlCD', 'Flexão com pegada fechada na bola medicinal', array['Comece em posição de prancha alta com as mãos na bola medicinal, na largura dos ombros.', 'Abaixe o corpo em direção ao solo flexionando os cotovelos, mantendo-os próximos às costelas.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre para voltar aos braços estendidos, mantendo a linha do corpo intacta.']),
  ('IGjKj1v', 'Remada baixa com pegada estreita na máquina', array['Ajuste a altura do assento e os apoios para os pés para garantir a postura correta.', 'Sente-se na máquina com os pés apoiados nos suportes e os joelhos levemente flexionados.', 'Posicione o tronco e permita que os braços se estendam para frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos com o tronco.', 'Estenda os brazos para frente novamente sem deixar o tronco oscilar.']),
  ('IGtBdNT', 'Rosca martelo sentada com halteres', array['Sente-se em um banco com um halter em cada mão, palmas voltadas para o tronco e braços estendidos para baixo.', 'Com a parte superior dos braços parada, expire e flexione os pesos enquanto contrai os bíceps.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione com as palmas voltadas uma para a outra e os cotovelos próximos ao corpo; evite balançar para trás.', 'Mantenha as palmas voltadas uma para a outra e os punhos retos.', 'Abaixe até que os cotovelos estejam quase estendidos, mantendo a parte superior dos braços imóvel.']),
  ('IH2kr7n', 'Encolhimento declinado com halteres', array['Ajuste um banco declinado em um ângulo de 45 graus.', 'Posicione-se de bruços no banco com o peito e o abdômen apoiados nele.', 'Deixe os braços estendidos e mantenha a cabeça neutra.', 'Eleve os ombros em direção às orelhas sem flexionar os cotovelos ou girar os ombros.', 'Suba e desça na vertical sem fazer círculos com os ombros.', 'Retorne o peso ou o corpo à posição inicial sem pressa.']),
  ('iK59oEA', 'Pullover deitado com halter na bola suíça', array['Sente-se em uma bola suíça e role para frente até que a parte superior das costas esteja apoiada na bola.', 'Pegue um halter com as duas mãos e estenda os braços para cima sobre o peito.', 'Encaixe as costelas e mantenha uma leve flexão nos cotovelos antes de descer o peso.', 'Desça o peso em arco atrás da cabeça até sentir um estiramento confortável nos ombros.', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio.', 'Puxe o peso de volta sobre o peito ao longo do mesmo arco, sem levantar as costelas.']),
  ('IL0JUxR', 'Barra fixa Gironda', array['Posicione-se de frente para a barra alta com uma postura estável e os pés na largura dos ombros.', 'Segure a barra com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados.', 'Incline-se para trás enquanto puxa, apontando o esterno em direção à barra e puxando os cotovelos para trás.', 'Evite balançar as pernas para passar da barra.', 'Desça com os braços estendidos sem despencar do topo.']),
  ('ila4NZS', 'Levantamento terra com barra', array['Fique em pé com os pés na largura dos ombros e a barra no chão à sua frente.', 'Flexione os joelhos e incline o quadril para abaixar o tronco e segurar a barra com as palmas voltadas para baixo, com as mãos um pouco além da largura dos ombros.', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás.', 'Empurre o quadril para trás mantendo a carga próxima e a coluna firme.', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar.', 'Projete o quadril para frente para ficar erguido sem inclinar para trás no topo.']),
  ('IMRsOCn', 'Squat jerk', array['Comece com a barra apoiada nos ombros e os pés na largura dos ombros.', 'Antes de se mover, abaixe o corpo em uma posição de agachamento, mantendo o peito erguido e os joelhos alinhados com os dedos dos pés.', 'Contraia o abdômen antes da puxada e mantenha a carga próxima ao corpo.', 'Empurre com as pernas e o quadril, depois guie o peso para a posição de recepção.', 'Receba a carga com o tronco contraído e os pés estáveis.', 'Fique em pé para finalizar, depois desça o peso de forma controlada antes da próxima repetição.']),
  ('iny3m5y', 'Dead bug', array['Deite-se de costas com os braços estendidos em direção ao teto.', 'Antes de se mover, flexione os joelhos e tire os pés do chão, formando um ângulo de 90 graus nos quadris e joelhos.', 'Contraia o tronco levemente antes de mover um membro.', 'Mova o braço ou a perna de trabalho mantendo o tronco firme e a respiração constante.', 'Evite que a pelve balance enquanto o braço ou a perna se movem.', 'Reajuste sua postura antes de trocar de lado ou iniciar a próxima repetição.']),
  ('Ion0XWz', 'Elevação posterior deitado no chão com halteres', array['Posicione-se de bruços no chão com um halter em cada mão, com as palmas voltadas uma para a outra.', 'Estenda os braços para a frente, mantendo uma leve flexão nos cotovelos.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Eleve os braços para fora e para trás com os cotovelos flexionados, deixando a parte posterior dos ombros fazer o trabalho.', 'Pare perto da altura dos ombros em vez de encolhê-los para levantar mais alto.', 'Abaixe os braços lentamente para os lados sem balançar o peso.']),
  ('ioTf098', 'Rosca polia alta na bola suíça', array['Sente-se em uma bola suíça e segure o puxador do cabo com as palmas voltadas para cima.', 'Estenda os braços totalmente para cima, mantendo os cotovelos próximos às orelhas.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio.', 'Desça até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('iPm26QU', 'Salto para baixo da caixa com estabilização unilateral', array['Posicione-se em frente a uma caixa ou plataforma com os pés na largura dos ombros.', 'Antes de se mover, flexione os joelhos e salte para cima da caixa, aterrissando suavemente com um pé na caixa e o outro pé pendurado na borda.', 'Flexione levemente os quadris e os joelhos para preparar o salto.', 'Carregue as pernas com uma pequena flexão, impulsione através do chão e aterrisse suavemente.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Absorva a aterrissagem através dos quadris e joelhos antes de repetir; alterne os lados quando a série exigir.']),
  ('IpONWYv', 'Flexão lateral com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em uma mão, deixando-o pendurado ao lado do corpo.', 'Com as costas retas e o core contraído, incline-se lateralmente na cintura com controle em direção ao lado oposto ao do halter, abaixando o peso o máximo que conseguir confortavelmente.', 'Fique em pé ou sentado com a pelve voltada para a frente.', 'Incline-se lateralmente pela cintura sem girar ou deixar os quadris se deslocarem.', 'Deixe a lateral do tronco trabalhar; não gire nem desloque os quadris.', 'Retorne o peso ou o corpo à posição inicial sem pressa.']),
  ('Iptlv6x', 'Remada alta com halteres (visão traseira)', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para baixo.', 'Deixe os halteres pendurados à frente das coxas, com os braços retos e as palmas voltadas para o corpo.', 'Posicione o torso e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a barra ou o peso em direção ao seu torso.', 'Traga os cotovelos para trás sem sacudir o torso.', 'Estenda os braços para a frente novamente sem deixar o torso oscilar.']),
  ('ipvgBnC', 'Elevação de panturrilha sentado com barra', array['Apoie ambos os pés enquanto estiver sentado em um banco; uma barra apoiada nas suas coxas.', 'Apoie a parte anterior dos pés em uma plataforma elevada, como um bloco ou degrau.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece estático.', 'Suba apoiando-se na parte anterior dos pés, levantando os calcanhares o mais alto possível sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('iQ241UP', 'Abdominal parcial', array['Deite-se de costas com os joelhos flexionados e os pés apoiados.', 'Coloque as mãos atrás da cabeça com os cotovelos apontando para fora.', 'Posicione a pelve e mantenha o pescoço relaxado antes de curvar para cima.', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o torso.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no torso.', 'Abaixe os ombros ou o torso com controle antes da próxima flexão.']),
  ('iqH55N8', 'Afundo para frente', array['Fique em pé com os pés na largura dos quadris e as mãos na cintura.', 'Dê um passo largo para a frente com o pé direito, abaixando o corpo em uma posição de afundo.', 'Ajuste sua base com largura suficiente para equilibrar antes de flexionar qualquer um dos joelhos.', 'Avance para o movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado.', 'Mantenha o pé da frente apoiado e evite colapsar para dentro no joelho.', 'Empurre através do pé da frente para retornar ao início, depois troque de perna conforme planejado.']),
  ('isAAZWA', 'Barra fixa pronada', array['Fique em pé com os pés na largura dos ombros e os joelhos semiflexionados.', 'Segure uma barra de pull-up com as palmas voltadas para baixo, mãos ligeiramente além da largura dos ombros.', 'Comece a partir de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas.', 'Evite balançar as pernas para ultrapassar a barra.', 'Desça até estender os braços sem cair repentinamente do topo.']),
  ('isofgzg', 'Alongamento de costas com rolo', array['Comece sentando-se no chão com as pernas estendidas à sua frente.', 'Posicione o rolo perpendicularmente ao seu corpo, logo abaixo dos glúteos.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('IU4QNJ6', 'Barra fixa com pegada supinada', array['Segure-se em uma barra fixa com as palmas das mãos voltadas para você e as mãos na largura dos ombros.', 'Contraia o tronco e puxe o corpo em direção à barra, liderando com o peito.', 'Comece a partir de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas.', 'Evite balançar as pernas para passar da barra.', 'Desça até os braços ficarem estendidos sem despencar repentinamente do topo.']),
  ('IvV6C9M', 'Rosca de punho neutra com halteres apoiada no banco', array['Sente-se em um banco com um halter em uma mão e o braço estendido sobre o banco, com a palma voltada para cima.', 'Mantenha a parte superior do braço fixa e flexione o halter em direção ao ombro, mantendo o punho em posição neutra.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço assumam a carga.', 'Movimente-se através dos punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que está trabalhando.', 'Retorne suavemente ao início sem deixar a carga cair das mãos; alterne os lados quando a série exigir.']),
  ('IwX5NqK', 'Rosca direta no banco Scott com cabo', array['Ajuste a polia para que o apoio do banco Scott fique na altura do peito.', 'Sente-se no banco Scott e apoie a parte superior dos braços no suporte, com as palmas para baixo e os cotovelos retos.', 'Posicione a parte superior do braço que está trabalhando contra o apoio Scott e deixe o cotovelo livre para dobrar.', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o suporte.', 'Mantenha o tronco quieto e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada.']),
  ('IxsFgRT', 'Giro judô com cabo', array['Fique de frente para a polia com uma base estável e os pés na largura dos ombros.', 'Segure o puxador do cabo com as duas mãos na altura do peito, com as palmas voltadas para baixo.', 'Posicione a pelve e faça o giro através da caixa torácica.', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível.', 'Mantenha o giro suave em vez de lançar os braços através do corpo.', 'Retorne pelo centro antes de girar para o outro lado.']),
  ('iYzB0Cz', 'Agachamento livre completo com barra', array['Fique em pé e posicione os pés na largura dos ombros, com as pontas dos pés ligeiramente viradas para fora.', 'Apoie a barra na parte superior das costas e faça uma pegada firme.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Dobre os quadris e os joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, reorganize sua base e respiração, depois inicie a próxima descida.']),
  ('izMnLqz', 'Desenvolvimento alternado com halteres', array['Fique em pé e posicione os pés na largura dos ombros, segurando um halter em cada mão na altura dos ombros.', 'Antes de se mover, empurre um halter acima da cabeça enquanto mantém o outro halter na altura do ombro.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído.', 'Conclua o movimento de um lado antes que o outro lado comece.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando a série exigir.']),
  ('iZop9xO', 'Tríceps testa com barra', array['Deite-se em um banco com os pés apoiados no chão e a cabeça na extremidade do banco.', 'Segure a barra com as palmas voltadas para baixo, as mãos na largura dos ombros e estenda os braços para cima sobre o peito.', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos.', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso.', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam.', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('IZVHb27', 'Afundo caminhando', array['Fique em pé e posicione os pés na largura dos ombros.', 'Dê um passo à frente com a perna direita, abaixando o corpo para a posição de afundo.', 'Posicione sua base larga o suficiente para equilibrar antes de dobrar qualquer um dos joelhos.', 'Dê o passo para o movimento e dobre ambos os joelhos, mantendo o pé da frente apoiado.', 'Mantenha o pé da frente apoiado e evite desabar para dentro na altura do joelho.', 'Empurre através do pé da frente para retornar ao início, depois mude de perna conforme planejado.']),
  ('J1vH2X0', 'Barra fixa com uma mão e peso', array['Segure a barra fixa com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Suspenda-se na barra com o braço esticado e o corpo reto.', 'Comece a partir de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas.', 'Evite balançar as pernas para passar da barra.', 'Desça até os braços ficarem estendidos, sem cair repentinamente do topo.']),
  ('J60bN17', 'Tríceps com apoio nos joelhos', array['Ajuste a máquina para o peso e a altura desejados.', 'Ajoelhe-se na almofada de frente para a máquina, com as mãos segurando os puxadores.', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis.', 'Pressione com as mãos para subir, depois ajuste os ombros antes de outra repetição.']),
  ('J6Dx1Mu', 'Supino com pegada fechada com barra', array['Posicione-se em um banco com os pés apoiados e as costas pressionadas contra o banco.', 'Segure a barra com uma pegada fechada, ligeiramente mais estreita que a largura dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('j6uIfep', 'Desenvolvimento com um braço com kettlebell com amplitude estendida no chão', array['Comece deitado de costas no chão com os joelhos flexionados e os pés apoiados.', 'Pegue um kettlebell com uma mão, com a palma voltada para os pés.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído.', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço em movimento.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando a série exigir.']),
  ('j74M6Zn', 'Elevação de panturrilha na parede com bola suíça (bola de tênis entre os joelhos)', array['Fique em pé com as costas contra uma parede e coloque uma bola suíça entre a parte inferior das costas e a parede.', 'Posicione os pés na largura dos ombros e ligeiramente à sua frente.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Abaixe os calcanhares em ritmo medido antes de subir novamente.']),
  ('J74XlNf', 'Rosca bicep alternada sentada com halteres na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Pegue um halter em cada mão com as palmas voltadas para a frente e os braços esticados.', 'Ajuste os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Conclua o movimento de um lado antes que o outro lado comece.', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada; alterne os lados quando a série exigir.']),
  ('j7XMAyn', 'Crucifixo na polia para a parte superior do peito', array['Conecte os puxadores aos cabos na altura do peito.', 'Posicione-se no centro da máquina de cabos com um pé ligeiramente à frente do outro.', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços.', 'Traga os puxadores pela frente do peito em um arco amplo, mantendo uma leve flexão nos cotovelos.', 'Mantenha o ângulo do cotovelo quase inalterado ao longo do arco.', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair.']),
  ('j9Q5crt', 'Caminhada no simulador de escada', array['Ajuste a máquina de escada para um nível confortável.', 'Suba na máquina e coloque as mãos nos corrimãos para se apoiar.', 'Fique em pé com a coluna firme e os ombros nivelados.', 'Caminhe em ritmo controlado, mantendo os ombros nivelados e os passos uniformes.', 'Mantenha os passos uniformes e evite se inclinar para longe da carga.', 'Pare antes que a postura comece a falhar, coloque a carga no chão com segurança e prepare-se para a próxima caminhada.']),
  ('J9zIWig', 'Afundo com elevação de joelho em movimento', array['Fique em pé e posicione os pés na largura dos quadris', 'Eleve o joelho direito em direção ao peito o mais alto possível enquanto se equilibra sobre a perna esquerda', 'Ajuste a base com largura suficiente para manter o equilíbrio antes de flexionar qualquer um dos joelhos', 'Avance para o movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado no chão', 'Mantenha o pé da frente apoiado e evite que o joelho desabe para dentro', 'Empurre com o pé da frente para retornar ao início e alterne as pernas conforme planejado']),
  ('JbC2iaV', 'Alongamento de coluna', array['Sente-se no chão com as pernas estendidas à sua frente', 'Coloque as mãos no chão atrás de você, com os dedos apontados para o corpo', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Avance suavemente em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais longe usando o momento', 'Mantenha a posição com respiração estável e solte devagar; repita do outro lado, se necessário']),
  ('jCBOdh0', 'Crucifixo declinado no cabo', array['Ajuste a polia na posição declinada', 'Fique de costas para a máquina com uma postura estável e pés na largura dos ombros', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco amplo', 'Mantenha o ângulo do cotovelo praticamente inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('jCrtE9b', 'Arremesso unilateral com medicine ball', array['Fique em pé com os pés na largura dos ombros, segurando a medicine ball com uma mão à frente da cintura', 'Flexione levemente os joelhos e contraia o tronco', 'Adote uma postura firme e deixe espaço livre suficiente para o deslocamento da bola', 'Empurre a bola com força, usando os braços e o tronco juntos; pegue-a ou recupere-a antes de reiniciar', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Retorne pelo mesmo caminho em ritmo controlado; alterne os lados quando a série exigir']),
  ('jdiExfW', 'Remada inclinada com fitas de suspensão', array['Prepare um equipamento de suspensão ou fitas na altura do peito', 'Fique de frente para o ponto de ancoragem e segure as manoplas com as palmas para baixo', 'Posicione o tronco e permita que os braços se estendam à frente sem curvar excessivamente as costas', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços à frente novamente sem deixar o tronco balançar']),
  ('jDnrkar', 'Supino reto unilateral com halteres com pegada neutra na bola suíça', array['Sente-se em uma bola suíça segurando um halter com uma mão', 'Dê um passo à frente com os pés e role o corpo para baixo até que a cabeça, o pescoço e a parte superior das costas estejam apoiados na bola', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando a série exigir']),
  ('jDOKRM5', 'Alongamento deitado de lado no chão', array['Deite-se de lado com as pernas esticadas e o braço de baixo estendido para cima ao lado da cabeça', 'Dobre o joelho de cima e apoie o pé no chão à frente da perna de baixo', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Avance suavemente em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais longe usando o momento', 'Mantenha a posição com respiração estável e solte devagar; repita do outro lado, se necessário']),
  ('jeHtrlO', 'Empurrão de peito com medicine ball de repetição única', array['Fique em pé com os pés na largura dos ombros, segurando a medicine ball na altura do peito', 'Estenda os braços à frente, empurrando a medicine ball para longe do peito', 'Adote uma postura firme e deixe espaço livre suficiente para o deslocamento da bola', 'Empurre a bola com força, usando os braços e o tronco juntos; pegue-a ou recupere-a antes de reiniciar', 'Acompanhe o movimento com o corpo todo, mantendo o controle da aterrissagem ou recepção', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('JF8AkMX', 'Rotação arqueiro em pé', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados', 'Estenda os braços para a frente na altura dos ombros, paralelos ao solo', 'Posicione a pelve e faça a rotação através da caixa torácica', 'Gire o tronco mantendo os quadris e a parte inferior do corpo o mais firmes possível', 'Mantenha a rotação suave em vez de lançar os braços pelo corpo', 'Retorne ao centro antes de girar para o outro lado']),
  ('jFtipLl', 'Agachamento noSmith', array['Prepare a máquina Smith com a barra na altura adequada para o seu agachamento', 'Fique em pé com os pés na largura dos ombros e pontas dos pés levemente viradas para fora', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés apoiados e joelhos alinhados com os pés', 'Empurre para cima com o peito e quadris subindo juntos; evite que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, então inicie a descida seguinte']),
  ('jgbvVJ0', 'Elevação T inclinada com halteres', array['Ajuste um banco inclinado a 45 graus e sente-se nele com um halter em cada mão, palmas viradas para dentro', 'Incline-se para a frente e deixe os braços estendidos para baixo, perpendiculares ao chão', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Abra os braços para os lados em formato de T, mantendo o tronco firme no banco', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para os lados sem balançar o peso']),
  ('JGKowMS', 'Remada baixa fechada no Smith', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as alças com as palmas para baixo, um pouco mais fechadas que a largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('jHAnWmT', 'Supino inclinado na máquina', array['Ajuste o assento e o encosto da máquina em uma posição confortável', 'Sente-se na máquina com as costas apoiadas no encosto e os pés firmes no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('JhYSVwT', 'Tríceps francês sentado com halter', array['Sente-se em um banco com a coluna reta e os pés firmes no chão', 'Segure um halter com ambas as mãos e estenda os braços para cima acima da cabeça', 'Posicione os braços firmes no lugar antes de estender os cotovelos', 'Mantenha os braços estáveis e estenda através dos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('jivWf8n', 'Rosca scott com halteres', array['Sente-se em um banco Scott com os braços apoiados no apoio e o peito encostado nele', 'Pegue um halter em cada mão com as palmas voltadas para cima e os braços estendidos', 'Posicione o braço que está trabalhando contra o apoio Scott e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto os braços permanecem em contato com o apoio', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
