  ('JsOV1SU', 'Muscle-up com peso', array['Comece pendurado em uma barra fixa com as palmas das mãos voltadas para a frente e as mãos ligeiramente acima da largura dos ombros', 'Firme o tronco e puxe o corpo em direção à barra, liderando com o peito', 'Comece a partir de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Abaixe até esticar os braços sem cair repentinamente do topo']),
  ('jtFKbt5', 'Rosca direta sentada com barra EZ', array['Apoie ambos os pés no chão enquanto estiver sentado em um banco; com as costas retas', 'Segure a barra EZ com as palmas das mãos voltadas para cima e as mãos na largura dos ombros', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
