  ('Kxquu2E', 'Afundo com barra', array['Posicione-se em frente a um banco ou degrau com uma barra apoiada na parte superior das costas', 'Coloque um pé no banco ou degrau, garantindo que todo o pé esteja em contato com a superfície', 'Apoie o pé da frente completamente na plataforma antes de transferir o peso para ele', 'Suba na plataforma e faça força através do pé da frente para ficar erguido sobre ele', 'Mantenha o pé da frente firme e evite colapsar o joelho para dentro', 'Empurre o pé da frente para retornar ao início e depois alterne as pernas conforme planejado']),
  ('KXyoEtA', 'Rosca bicep concentrada sentada com halteres', array['Apoie ambos os pés enquanto estiver sentado em um banco e segure um halter em cada mão com as palmas voltadas para cima', 'Apoie a parte superior dos braços nas coxas, deixando os halteres pendurados para baixo', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Desça até que os braços estejam quase estendidos, mantendo a parte superior dos braços imóvel']),
  ('ky8FLU8', 'Puxada frontal com pegada invertida na máquina', array['Ajuste o banco ao seu corpo e acomode-se na máquina', 'Segure as manoplas com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Sente-se erguido e posicione os ombros antes de puxar a manopla para baixo', 'Puxe a manopla para baixo direcionando os cotovelos para as costelas e mantenha o tronco firme', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás', 'Deixe a manopla subir de forma controlada até que os braços estejam estendidos e reposicione os ombros']),
  ('Kyd9Rz5', 'Desenvolvimento militar em pé com barra e pegada aberta', array['Fique em pé com os pés na largura dos ombros e segure a barra com as palmas voltadas para baixo, ligeiramente mais aberta que a largura dos ombros', 'Antes de se mover, levante a barra até a altura dos ombros mantendo os cotovelos ligeiramente à frente da barra', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Pressione o peso ou as manoplas para cima mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('KyLtiLT', 'Extensão de tríceps inclinada com barra EZ', array['Ajuste o banco para aproximadamente 45 graus', 'Sente-se no banco com as costas apoiadas no estofamento e segure a barra EZ com as palmas voltadas para baixo', 'Posicione a parte superior dos braços antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda os cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('Kzg30R7', 'Abdominal em pé com elástico', array['Conecte o elástico a um ponto de fixação firme na altura da cintura', 'Fique de costas para o ponto de fixação em uma base estável com os pés na largura dos ombros', 'Posicione a pelve e mantenha o pescoço relaxado antes de fazer a flexão do tronco', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Desça os ombros ou o tronco de forma controlada antes do próximo movimento']),
  ('KZn52RC', 'Abdominal com pernas flexionadas e braços estendidos', array['Deite-se de costas com as pernas estendidas e os braços estendidos acima da cabeça', 'Contraindo o abdômen, eleve o tronco do chão enquanto levanta simultaneamente as pernas em direção ao peito', 'Posicione a pelve e mantenha o pescoço relaxado antes de curvar para cima', 'Curve a caixa torácica em direção à pelve, permitindo que os abdominais movimentem o tronco', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima curvatura']),
  ('KZXAtKQ', 'Flexão com pegada fechada sobre halteres', array['Inicie em posição de flexão com as mãos próximas, diretamente sob os ombros', 'Segure um halter em cada mão, apoiando-os no chão', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta até esticar os braços, mantendo a linha do corpo intacta']),
  ('L2V5Nan', 'Extensão deitada com halter cruzando o rosto', array['Deite-se em um banco com os pés apoiados e a cabeça na extremidade do banco', 'Pegue um halter com as duas mãos e estenda os braços para cima acima do peito, com as palmas viradas uma para a outra', 'Posicione os braços firmes antes de estender os cotovelos', 'Mantenha os braços estáveis e estenda através dos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('L4ay0PW', 'Figura 8 com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em uma mão', 'Flexione levemente os joelhos e incline-se para a frente a partir do quadril, com a coluna firme', 'Posicione a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível', 'Mantenha o giro suave em vez de lançar os braços pelo corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('L68dTQj', 'Rotação sentada com elástico', array['Sente-se no chão com as pernas estendidas à frente e as costas retas', 'Passe o elástico ao redor da cintura e segure as pontas com ambas as mãos', 'Posicione a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível', 'Controle o elástico no retorno em vez de deixar que ele puxe você bruscamente', 'Retorne pelo centro antes de girar para o outro lado']),
  ('laVRfDf', 'Elevação frontal em pé com halteres acima da cabeça', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para baixo', 'Mantenha os braços retos e levante os halteres à sua frente, erguendo-os acima da cabeça', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Levante os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco parado', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto', 'Abaixe os braços lentamente para as laterais sem balançar o peso'])
